import csv
import json
import os
import sys

from pyscipopt import Model, quicksum

APP = "/app"
DATA = os.path.join(APP, "data")
SUB = os.path.join(APP, "submissions")
os.makedirs(SUB, exist_ok=True)

# ---------------- Load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    cfg = json.load(f)

BATTERY_COST = float(cfg["battery_lease_cost"])
UNSERVED_PEN = float(cfg["unserved_penalty_per_package"])
TOL = float(cfg.get("feasibility_tolerance", 1e-5))
GAP = float(cfg.get("solver_mip_gap", 0.0005))

bases = {}
base_order = []
with open(os.path.join(DATA, "bases.csv")) as f:
    for row in csv.DictReader(f):
        b = row["base_id"]
        bases[b] = {
            "open_cost": float(row["open_cost"]),
            "sorties": int(row["daily_sortie_capacity"]),
            "batt_slots": int(row["battery_slots"]),
            "pilot_hours": float(row["pilot_shift_hours"]),
        }
        base_order.append(b)

zones = {}
zone_order = []
with open(os.path.join(DATA, "demand_zones.csv")) as f:
    for row in csv.DictReader(f):
        z = row["zone_id"]
        zones[z] = {
            "demand": int(row["packages"]),
            "priority": int(row["medical_priority"]),
            "rate": float(row["minimum_service_rate"]),
        }
        zone_order.append(z)

arcs = {}
arc_list = []
with open(os.path.join(DATA, "base_zone_arcs.csv")) as f:
    for row in csv.DictReader(f):
        z = row["zone_id"]
        b = row["base_id"]
        arcs[(b, z)] = {
            "km": float(row["round_trip_km"]),
            "tmin": float(row["flight_minutes"]),
            "payload": int(row["max_payload_packages"]),
            "cost": float(row["cost_per_package"]),
        }
        arc_list.append((b, z))

# ---------------- Preprocessing ----------------
# Max unmet allowed per zone (integer-safe)
max_unmet = {z: int((1.0 - zones[z]["rate"]) * zones[z]["demand"] + 1e-9) for z in zone_order}
min_served = {z: zones[z]["demand"] - max_unmet[z] for z in zone_order}

# Arc upper bound: min(payload, demand)
arc_ub = {(b, z): min(arcs[(b, z)]["payload"], zones[z]["demand"]) for (b, z) in arc_list}

# ---------------- Model ----------------
model = Model("drone_base_delivery")
model.setParam("gaprel", GAP)

time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

y = {}
for b in base_order:
    y[b] = model.addVar(name=f"y_{b}", vtype="B", lb=0, ub=1, obj=bases[b]["open_cost"])

L = {}
for b in base_order:
    L[b] = model.addVar(name=f"L_{b}", vtype="I", lb=0, ub=bases[b]["batt_slots"], obj=BATTERY_COST)

x = {}
s = {}
for (b, z) in arc_list:
    a = arcs[(b, z)]
    ub = arc_ub[(b, z)]
    x[(b, z)] = model.addVar(name=f"x_{b}_{z}", vtype="I", lb=0, ub=ub, obj=a["cost"])
    s[(b, z)] = model.addVar(name=f"s_{b}_{z}", vtype="I", lb=0, ub=ub // a["payload"] if a["payload"] else ub, obj=0.0)

u = {}
for z in zone_order:
    u[z] = model.addVar(name=f"u_{z}", vtype="I", lb=0, ub=max_unmet[z], obj=UNSERVED_PEN)

# Objective: explicit expression from stored coefficients
obj_terms = []
for b in base_order:
    obj_terms.append(bases[b]["open_cost"] * y[b])
for b in base_order:
    obj_terms.append(BATTERY_COST * L[b])
for (b, z) in arc_list:
    obj_terms.append(arcs[(b, z)]["cost"] * x[(b, z)])
for z in zone_order:
    obj_terms.append(UNSERVED_PEN * u[z])
model.setObjective(quicksum(obj_terms), sense="minimize")

# Constraints
# 1) Demand balance
for z in zone_order:
    model.addCons(
        quicksum(x[(b, z)] for (b, z2) in arc_list if z2 == z) + u[z] == zones[z]["demand"],
        name=f"demand_{z}",
    )

# 2) Service rate (unmet cap already via ub; add explicit for clarity)
for z in zone_order:
    model.addCons(u[z] <= max_unmet[z], name=f"svc_{z}")

# 3) Arc: x <= payload * sorties ; x <= demand * y ; link sorties to x
for (b, z) in arc_list:
    a = arcs[(b, z)]
    P = a["payload"]
    model.addCons(x[(b, z)] <= P * s[(b, z)], name=f"pay_{b}_{z}")
    model.addCons(x[(b, z)] <= zones[z]["demand"] * y[b], name=f"gate_{b}_{z}")
    # sorties only if flow
    model.addCons(s[(b, z)] <= x[(b, z)], name=f"slink_{b}_{z}")

# 4) Base sortie capacity
for b in base_order:
    model.addCons(
        quicksum(s[(b, z)] for (b2, z) in arc_list if b2 == b) <= bases[b]["sorties"] * y[b],
        name=f"sortie_{b}",
    )

# 5) Pilot hours: sum t * sorties <= 60 H y
for b in base_order:
    model.addCons(
        quicksum(arcs[(b, z)]["tmin"] * s[(b, z)] for (b2, z) in arc_list if b2 == b)
        <= 60.0 * bases[b]["pilot_hours"] * y[b],
        name=f"pilot_{b}",
    )

# 6) Battery slot-minutes: sum t * sorties <= 60 H * L_b ; L <= K y
for b in base_order:
    model.addCons(
        quicksum(arcs[(b, z)]["tmin"] * s[(b, z)] for (b2, z) in arc_list if b2 == b)
        <= 60.0 * bases[b]["pilot_hours"] * L[b],
        name=f"batt_{b}",
    )
    model.addCons(L[b] <= bases[b]["batt_slots"] * y[b], name=f"battgate_{b}")

# ---------------- Solve ----------------
status = "unknown"
objval = None
try:
    model.optimize()
    status = model.getStatus()
    print("SCIP Status:", status)
    if model.getNSols() > 0:
        objval = model.getObjVal()
        print("Objective:", objval)
except Exception as e:
    print("Solver error:", e)
    status = "error"

# ---------------- Extract solution ----------------
sol = None
if model.getNSols() > 0:
    try:
        sol = model.getBestSol()
    except Exception as e:
        print("getBestSol error:", e)
        sol = None

def val(var):
    if sol is not None:
        return model.getVal(var)
    return 0.0

y_val = {b: int(round(val(y[b]))) for b in base_order}
L_val = {b: int(round(val(L[b]))) for b in base_order}
x_val = {(b, z): int(round(val(x[(b, z)]))) for (b, z) in arc_list}
s_val = {(b, z): int(round(val(s[(b, z)]))) for (b, z) in arc_list}
u_val = {z: int(round(val(u[z]))) for z in zone_order}

# Fallback heuristic if no solution: open all bases, greedy nearest assignment
if sol is None:
    print("No MIP solution; using heuristic fallback.")
    y_val = {b: 1 for b in base_order}
    u_val = {z: 0 for z in zone_order}
    x_val = {(b, z): 0 for (b, z) in arc_list}
    s_val = {(b, z): 0 for (b, z) in arc_list}
    # per-base remaining sorties / pilot minutes / battery minutes
    rem_sortie = {b: float(bases[b]["sorties"]) for b in base_order}
    rem_pilot = {b: 60.0 * bases[b]["pilot_hours"] for b in base_order}
    rem_batt = {b: 60.0 * bases[b]["pilot_hours"] * bases[b]["batt_slots"] for b in base_order}
    for z in zone_order:
        need = min_served[z]
        # sort arcs by cost
        cand = sorted([b for (b, z2) in arc_list if z2 == z], key=lambda b: arcs[(b, z)]["cost"])
        for b in cand:
            if need <= 0:
                break
            a = arcs[(b, z)]
            P = a["payload"]
            # max packages we can send on this arc given remaining capacities
            maxpk = min(arc_ub[(b, z)], need, int(rem_sortie[b] * P), int(rem_pilot[b] / a["tmin"] * P), int(rem_batt[b] / a["tmin"] * P))
            if maxpk <= 0:
                continue
            # use full sorties as much as possible
            nsort = maxpk // P
            if nsort < 1 and maxpk > 0:
                nsort = 1
            pk = min(maxpk, nsort * P)
            if pk <= 0:
                continue
            x_val[(b, z)] += pk
            s_val[(b, z)] += nsort
            rem_sortie[b] -= nsort
            rem_pilot[b] -= nsort * a["tmin"]
            rem_batt[b] -= nsort * a["tmin"]
            need -= pk
        u_val[z] = zones[z]["demand"] - sum(x_val[(b, z)] for (b, z2) in arc_list if z2 == z)
        # if still short of min served, allow up to max_unmet only; if worse, we cannot fix (infeasible instance)
    L_val = {}
    for b in base_order:
        if y_val[b] == 0:
            L_val[b] = 0
        else:
            # minimal packs: ceil(total flight minutes / (60 H))
            tot = sum(arcs[(b, z)]["tmin"] * s_val[(b, z)] for (b2, z) in arc_list if b2 == b)
            import math
            L_val[b] = min(bases[b]["batt_slots"], max(0, math.ceil(tot / (60.0 * bases[b]["pilot_hours"] - 1e-9))))

# ---------------- Validation ----------------
print("--- Validation ---")
ok = True
for z in zone_order:
    served = sum(x_val[(b, z)] for (b, z2) in arc_list if z2 == z)
    unmet = u_val[z]
    if abs(served + unmet - zones[z]["demand"]) > TOL:
        print(f"FAIL demand balance {z}: served={served} unmet={unmet} D={zones[z]['demand']}")
        ok = False
    if unmet > max_unmet[z] + TOL:
        print(f"FAIL service rate {z}: unmet={unmet} max={max_unmet[z]}")
        ok = False
for (b, z) in arc_list:
    P = arcs[(b, z)]["payload"]
    if x_val[(b, z)] > P * s_val[(b, z)] + TOL:
        print(f"FAIL payload {b}->{z}: x={x_val[(b,z)]} P*s={P*s_val[(b,z)]}")
        ok = False
    if x_val[(b, z)] > 0 and y_val[b] == 0:
        print(f"FAIL gating {b}->{z} base closed")
        ok = False
for b in base_order:
    tot_s = sum(s_val[(b, z)] for (b2, z) in arc_list if b2 == b)
    if tot_s > bases[b]["sorties"] * y_val[b] + TOL:
        print(f"FAIL sorties {b}: {tot_s} > {bases[b]['sorties']}*{y_val[b]}")
        ok = False
    tot_pm = sum(arcs[(b, z)]["tmin"] * s_val[(b, z)] for (b2, z) in arc_list if b2 == b)
    if tot_pm > 60.0 * bases[b]["pilot_hours"] * y_val[b] + 1e-6:
        print(f"FAIL pilot {b}: {tot_pm:.2f} > {60.0*bases[b]['pilot_hours']*y_val[b]:.2f}")
        ok = False
    if tot_pm > 60.0 * bases[b]["pilot_hours"] * L_val[b] + 1e-6:
        print(f"FAIL battery {b}: {tot_pm:.2f} > {60.0*bases[b]['pilot_hours']*L_val[b]:.2f}")
        ok = False
    if L_val[b] > bases[b]["batt_slots"] * y_val[b] + TOL:
        print(f"FAIL batt gate {b}")
        ok = False
print("Validation", "PASSED" if ok else "FAILED")

# ---------------- Write solution.csv ----------------
sol_path = os.path.join(SUB, "solution.csv")
rows = []
for b in base_order:
    if y_val[b] == 1:
        rows.append(["open", b, "", "1"])
for b in base_order:
    if y_val[b] == 1 and L_val[b] > 0:
        rows.append(["battery", b, "", str(L_val[b])])
for (b, z) in arc_list:
    if x_val[(b, z)] > 0:
        rows.append(["assignment", b, z, str(x_val[(b, z)])])
for z in zone_order:
    if u_val[z] > 0:
        rows.append(["unmet", "", z, str(u_val[z])])

with open(sol_path, "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["row_type", "base_id", "zone_id", "value"])
    w.writerows(rows)
print(f"Wrote {sol_path} rows: {len(rows)}")

